import{_ as r,o as a,c as i,ae as t}from"./chunks/framework.BvHJbMD4.js";const o="/assets/Bookcover.xGoqTKpl.jpg",m=JSON.parse('{"title":"Building Embedded Systems with Linux, Raspberry Pi and ELBE","description":"","frontmatter":{},"headers":[],"relativePath":"book.md","filePath":"book.md"}'),n={name:"book.md"};function s(l,e,d,p,b,h){return a(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="building-embedded-systems-with-linux-raspberry-pi-and-elbe" tabindex="-1">Building Embedded Systems with Linux, Raspberry Pi and ELBE <a class="header-anchor" href="#building-embedded-systems-with-linux-raspberry-pi-and-elbe" aria-label="Permalink to &quot;Building Embedded Systems with Linux, Raspberry Pi and ELBE&quot;">​</a></h1><p>A practical guide to building <strong>reproducible embedded Linux systems</strong> using the <strong>ELBE build environment</strong> and <strong>Raspberry Pi</strong>.</p><p><img src="'+o+'" alt="Book Cover"></p><hr><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p><em>Building Embedded Systems with Linux, Raspberry Pi and ELBE</em> focuses on practical workflows for constructing Debian-based embedded Linux systems using the <strong>ELBE (Embedded Linux Build Environment)</strong>.</p><p>Instead of distributing static system images, the book demonstrates how to treat the operating system as a <strong>reproducible build artifact</strong>, allowing developers to consistently generate root filesystems and system images.</p><p>The examples use <strong>Raspberry Pi</strong> as the primary development platform, enabling readers to experiment with embedded Linux development on accessible hardware.</p><p>The book provides step-by-step guidance on configuring build environments, customizing systems, and creating deployable embedded Linux images.</p><hr><h2 id="what-you-will-learn" tabindex="-1">What You Will Learn <a class="header-anchor" href="#what-you-will-learn" aria-label="Permalink to &quot;What You Will Learn&quot;">​</a></h2><ul><li>Building embedded Linux systems using <strong>ELBE</strong></li><li>Creating reproducible root filesystems with <strong>Debian</strong></li><li>Managing packages and customizing system images</li><li>Generating deployable <strong>Raspberry Pi</strong> system images</li><li>Working with modern storage configurations</li><li>Integrating containers and virtualization environments</li><li>Developing structured build workflows for embedded Linux projects</li></ul><hr><h2 id="practical-recipes-included" tabindex="-1">Practical Recipes Included <a class="header-anchor" href="#practical-recipes-included" aria-label="Permalink to &quot;Practical Recipes Included&quot;">​</a></h2><p>Hands-on build recipes include:</p><ul><li>Docker build environments</li><li>Desktop environments</li><li>QEMU ARM virtual platforms</li><li>Raspberry Pi minimal images</li><li>Btrfs filesystems</li><li>OverlayFS and SquashFS systems</li><li>Encrypted filesystems</li><li>Podman container environments</li><li>Custom Raspberry Pi kernel builds</li><li>LLM development machine on Raspberry Pi 5</li><li>ROS2 development environment</li></ul><hr><h2 id="example-code" tabindex="-1">Example Code <a class="header-anchor" href="#example-code" aria-label="Permalink to &quot;Example Code&quot;">​</a></h2><p>All ELBE build recipes used in the book are available on GitHub:</p><p><strong>ELBE Cookbook Recipes</strong></p><p><a href="https://github.com/rootfx-io/elbe-cookbook-recipes" target="_blank" rel="noreferrer">https://github.com/rootfx-io/elbe-cookbook-recipes</a></p><p>These examples allow readers to reproduce the systems described in the book and experiment with ELBE-based embedded Linux workflows.</p><hr><h2 id="foreword" tabindex="-1">Foreword <a class="header-anchor" href="#foreword" aria-label="Permalink to &quot;Foreword&quot;">​</a></h2><p>The foreword was written by <strong>John Ogness</strong>, core developer and original contributor to the ELBE project at Linutronix.</p><hr><h2 id="sponsor" tabindex="-1">Sponsor <a class="header-anchor" href="#sponsor" aria-label="Permalink to &quot;Sponsor&quot;">​</a></h2><p>This work was sponsored by <strong>AFRA GmbH</strong>, a software engineering company based in Erlangen, Germany specializing in embedded and automation systems.</p><p><a href="https://www.afra.de" target="_blank" rel="noreferrer">https://www.afra.de</a></p><hr><h2 id="availability" tabindex="-1">Availability <a class="header-anchor" href="#availability" aria-label="Permalink to &quot;Availability&quot;">​</a></h2><p>The book is available in printed and digital formats.</p><p>📖 <strong>Book link</strong></p><p><a href="https://kdpbook.link/for/3982834406" target="_blank" rel="noreferrer">https://kdpbook.link/for/3982834406</a></p><hr><h2 id="about-the-author" tabindex="-1">About the Author <a class="header-anchor" href="#about-the-author" aria-label="Permalink to &quot;About the Author&quot;">​</a></h2><p>Krishna Pattabiraman is an embedded systems technologist with nearly two decades of professional experience in Linux-based product development. His work spans embedded Linux system architecture, kernel customization, system integration, and deployment across multiple industries.</p><p>He is passionate about creating practical tools and sharing hands-on engineering knowledge with developers and learners in the embedded Linux community.</p><hr><h2 id="related-resources" tabindex="-1">Related Resources <a class="header-anchor" href="#related-resources" aria-label="Permalink to &quot;Related Resources&quot;">​</a></h2><ul><li><p>ELBE Build Environment<br><a href="https://elbe-rfs.org" target="_blank" rel="noreferrer">https://elbe-rfs.org</a></p></li><li><p>Raspberry Pi Platform<br><a href="https://www.raspberrypi.com" target="_blank" rel="noreferrer">https://www.raspberrypi.com</a></p></li><li><p>Debian Project<br><a href="https://www.debian.org" target="_blank" rel="noreferrer">https://www.debian.org</a></p></li></ul>',41)])])}const c=r(n,[["render",s]]);export{m as __pageData,c as default};
